const input = $('Permissioned Query Input').first().json;
const question = typeof input.query === 'string' ? input.query.trim() : '';
if (!question) throw new Error('A natural-language read request is required.');
const dateContext = $('Validate Session Before Retrieval').first().json?.message?.date_context;
const currentDate = String(dateContext?.current_date || '');
const currentYear = Number(dateContext?.current_year);
const datePattern = /^\d{4}-\d{2}-\d{2}$/;
if (!datePattern.test(currentDate) || !Number.isInteger(currentYear) || currentYear !== Number(currentDate.slice(0, 4)) || dateContext?.current_year_start !== `${currentYear}-01-01` || dateContext?.current_year_end !== `${currentYear}-12-31` || !datePattern.test(String(dateContext?.current_month_start || '')) || !datePattern.test(String(dateContext?.current_month_end || '')) || typeof dateContext?.time_zone !== 'string' || !dateContext.time_zone || dateContext.time_zone.length > 64) throw new Error('Frappe returned an invalid authoritative date context.');
const rawSql = /```(?:sql|mysql|mariadb|postgresql)?/i.test(question) || /(?:^|[\s;(])(?:select\s+.+?\s+from|insert\s+into|update\s+[^\s;]+\s+set|delete\s+from|drop\s+(?:table|database)|alter\s+table|truncate\s+table|create\s+(?:table|database|index)|grant\s+|revoke\s+|merge\s+into|exec(?:ute)?\s+|call\s+)/is.test(question) || /\b(?:from|join)\s+[`\"']?(?:tab[A-Za-z0-9_]+|__[A-Za-z0-9_]+)/i.test(question) || /\b(?:union\s+select|information_schema|pg_catalog|frappe\.db\.sql|cursor\.execute)\b/i.test(question);
const writeIntent = /^(?:please\s+)?(?:delete|remove|erase|update|change|edit|modify|insert|create|add|write|set)\b/i.test(question) || /^(?:請|请)?(?:刪除|删除|移除|更新|修改|新增|建立|创建|寫入|写入)/.test(question);
const sensitiveRequest = /\b(?:password|passphrase|api[ -]?key|secret|access[ -]?token|session[ -]?id|credential|cookie)\b/i.test(question) || /(?:密碼|密码|口令|金鑰|金钥|密鑰|密钥|秘鑰|秘钥|權杖|令牌|憑證|凭证)/.test(question);
const injectionAttempt = /\b(?:ignore|disregard|override|bypass)\b.{0,50}\b(?:instruction|prompt|permission|security|policy|rule)\b/is.test(question) || /\b(?:jailbreak|act as (?:an? )?(?:administrator|admin|root)|developer mode)\b/i.test(question);
if (rawSql || writeIntent || sensitiveRequest || injectionAttempt) throw new Error('Only safe natural-language, read-only ERPNext questions are accepted.');
return [{ json: { question, dateContext } }];

const validated = $('Validate Natural-language Read Request').first().json;
const input = $('Permissioned Query Input').first().json;
const question = validated.question;
const dateContext = validated.dateContext;
const matches = $input.all().flatMap((item) => Array.isArray(item.json) ? item.json : [item.json]);
if (!matches.length) throw new Error('No allowlisted schema metadata matched this question.');
const contents = matches.map((row) => row.content).filter((value) => typeof value === 'string' && value.trim());
const schema = contents.join('\n\n---\n\n');
const doctypes = [...new Set(contents.flatMap((content) => [...content.matchAll(/^ERPNext DocType(?: fields)?:\s*(.+)$/gmi)].map((match) => match[1].trim())).filter(Boolean))];
const normalizedQuestion = question.toLocaleLowerCase('en').replace(/[\s_]+/g, ' ').trim();
const countIntent = /\b(?:how many|count|number of|total(?: number)?(?: of)?)\b/i.test(question) || /(?:多少|幾多|几多|總共有|总共有|共有|總數|总数|紀錄數|記錄數|记录数|筆數|笔数)/.test(question);
let deterministicDoctype = doctypes.find((doctype) => normalizedQuestion.includes(doctype.toLocaleLowerCase('en'))) || '';
if (!deterministicDoctype && normalizedQuestion.includes('example client database') && doctypes.includes('Example Master')) deterministicDoctype = 'Example Master';
if (countIntent && deterministicDoctype) {
  const plan = { version: '1', doctype: deterministicDoctype, fields: [], filters: [], order_by: [], offset: 0, limit: 20, aggregates: [{ function: 'count', field: '*' }], group_by: [] };
  return [{ json: { route: 'deterministic', queryPlan: JSON.stringify(plan), sessionToken: input.sessionToken, sessionId: input.sessionId } }];
}
const contract = { version: '1', doctype: 'ONE allowlisted DocType', fields: ['fieldname'], filters: [{ field: 'fieldname', operator: '=', value: 'value' }], order_by: [{ field: 'fieldname', direction: 'asc' }], offset: 0, limit: 20, aggregates: [{ function: 'count|sum|average|minimum|maximum', field: '* or fieldname' }], group_by: ['fieldname'] };
const temporalContext = `Current ERPNext date: ${dateContext.current_date}\nCurrent ERPNext year: ${dateContext.current_year}\nCurrent-year range: ${dateContext.current_year_start} through ${dateContext.current_year_end}\nCurrent-month range: ${dateContext.current_month_start} through ${dateContext.current_month_end}\nERPNext time zone: ${dateContext.time_zone}`;
const prompt = `Convert the user's ERPNext data question into QueryPlanV1 JSON. Return JSON only. Always include every top-level key in the contract; use empty arrays when a section is unused. Never return SQL, code, writes, joins, expressions, or more than one DocType. Use only DocTypes and fields present in the supplied schema. Resolve ordinary natural-language business names, translated labels, and abbreviations against the supplied DocType name, label, and description; for example, a business phrase may validly refer to an allowlisted DocType without using its exact technical name. In this deployment, the business phrase example client database means the allowlisted Example Master DocType when Example Master is present in the supplied schema. This alias does not grant access and must never be used to redirect a denied system-table or credential request. Do not invent an unrelated DocType or field. The AUTHORITATIVE ERPNext DATE CONTEXT below is server-supplied and overrides model knowledge, training dates, and prior conversation. Resolve relative time phrases in every language against it. In particular, this year, current year, 今年, and 本年 mean exactly ${dateContext.current_year_start} through ${dateContext.current_year_end}. Today means ${dateContext.current_date}. This month means exactly ${dateContext.current_month_start} through ${dateContext.current_month_end}. Never guess the current date or year. Use explicit date filters when the question is relative to time. Supported filter operators: =, !=, >, >=, <, <=, in, not in, like, not like, between, is. Keep limit at or below 100. For ordinary lists use empty aggregates and group_by arrays. For aggregates, fields may contain only group_by fields. Contract example: ${JSON.stringify(contract)}\n\nAUTHORITATIVE ERPNEXT DATE CONTEXT:\n${temporalContext}\n\nSCHEMA METADATA ONLY:\n${schema}\n\nUSER QUESTION:\n${question}`;
return [{ json: { route: 'gemini', prompt } }];

const text = $json?.candidates?.[0]?.content?.parts?.map((part) => part.text || '').join('') || '';
const cleaned = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let plan;
try { plan = JSON.parse(cleaned); } catch { throw new Error('Gemini did not return valid QueryPlanV1 JSON.'); }
if (!plan || Array.isArray(plan) || typeof plan !== 'object') throw new Error('QueryPlanV1 must be a JSON object.');
const allowedKeys = new Set(['version', 'doctype', 'fields', 'filters', 'order_by', 'offset', 'limit', 'aggregates', 'group_by']);
if (Object.keys(plan).some((key) => !allowedKeys.has(key))) throw new Error('Gemini returned unsupported QueryPlanV1 keys.');
if (plan.version !== '1' || typeof plan.doctype !== 'string' || !plan.doctype.trim()) throw new Error('Gemini returned an incomplete QueryPlanV1 object.');
for (const key of ['fields', 'filters', 'order_by', 'aggregates', 'group_by']) if (!Array.isArray(plan[key])) throw new Error(`Gemini returned invalid QueryPlanV1 ${key}.`);
if (!Number.isInteger(plan.offset) || !Number.isInteger(plan.limit)) throw new Error('Gemini returned invalid QueryPlanV1 pagination.');
if (plan.aggregates.length) plan.fields = [...plan.group_by];
const input = $('Permissioned Query Input').first().json;
return [{ json: { queryPlan: JSON.stringify(plan), sessionToken: input.sessionToken, sessionId: input.sessionId } }];

const result = $json.message;
if (!result || !Array.isArray(result.rows)) throw new Error('Frappe returned an invalid query result.');
let notice = '';
if (result.truncated) notice = ` Results were truncated to ${result.limit} rows; ask for the next page using offset ${result.offset + result.limit}.`;
return [{ json: { output: JSON.stringify({ ...result, notice }) } }];
